import java.util.*;

class Solution {
    public int[] maxNumber(int[] a, int[] b, int k) {
        int[] best = new int[k];
        for (int i = Math.max(0, k - b.length); i <= Math.min(k, a.length); i++) {
            int[] cand = merge(pick(a, i), pick(b, k - i));
            if (greater(cand, 0, best, 0)) best = cand;
        }
        return best;
    }

    // largest subsequence of length t, using a decreasing stack
    private int[] pick(int[] nums, int t) {
        int[] st = new int[t];
        int top = 0, drop = nums.length - t;
        for (int x : nums) {
            while (top > 0 && st[top - 1] < x && drop > 0) { top--; drop--; }
            if (top < t) st[top++] = x;
            else drop--;                         // stack full: this digit is dropped
        }
        return st;
    }

    // greedy merge: always take from the larger remaining suffix
    private int[] merge(int[] x, int[] y) {
        int[] out = new int[x.length + y.length];
        int i = 0, j = 0;
        for (int p = 0; p < out.length; p++) {
            out[p] = greater(x, i, y, j) ? x[i++] : y[j++];
        }
        return out;
    }

    // is x[i..] lexicographically greater than y[j..]?
    private boolean greater(int[] x, int i, int[] y, int j) {
        while (i < x.length && j < y.length && x[i] == y[j]) { i++; j++; }
        return j == y.length || (i < x.length && x[i] > y[j]);
    }
}

