class Solution:
    def maxNumber(self, a: List[int], b: List[int], k: int) -> List[int]:
        def pick(nums, t):
            drop = len(nums) - t; st = []
            for x in nums:
                while drop and st and st[-1] < x: st.pop(); drop -= 1
                st.append(x)
            return st[:t]
        def merge(x, y):
            out = []
            while x or y:
                if x > y: out.append(x[0]); x = x[1:]
                else: out.append(y[0]); y = y[1:]
            return out
        best = []
        for i in range(max(0, k - len(b)), min(k, len(a)) + 1):
            best = max(best, merge(pick(a, i), pick(b, k - i)))
        return best

