function maxNumber(a, b, k) {
  const greater = (x, i, y, j) => { while (i < x.length && j < y.length && x[i] === y[j]) { i++; j++; } return j === y.length || (i < x.length && x[i] > y[j]); };
  const pick = (nums, t) => {
    // choose t digits: at each step the largest digit (leftmost) in the feasible window
    const out = []; let start = 0;
    for (let r = 0; r < t; r++) { const end = nums.length - (t - r); let bi = start; for (let i = start; i <= end; i++) if (nums[i] > nums[bi]) bi = i; out.push(nums[bi]); start = bi + 1; }
    return out;
  };
  const merge = (x, y) => { const out = []; let i = 0, j = 0; while (i < x.length || j < y.length) { if (greater(x, i, y, j)) out.push(x[i++]); else out.push(y[j++]); } return out; };
  let best = null;
  for (let i = Math.max(0, k - b.length); i <= Math.min(k, a.length); i++) {
    const c = merge(pick(a, i), pick(b, k - i));
    if (best === null || greater(c, 0, best, 0)) best = c;
  }
  return best;
}
